/**
 * C ref: shk.c:1278
 * @param {CLongLong} tmp
 * @param {CPtr<struct monst>} shkp
 * @returns {CLongLong}
 */
function* check_credit(tmp, shkp) {
    let credit = cptr.ldI64o(
        (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
        $eshk_credit
    );

    if (credit == 0n) {
        ;  /* nothing to do; just 'return tmp;' */
    } else if (credit >= tmp) {
        (yield* pline_The(__s_price_is_deducted_from_your_credit));
        cptr.stI64o(
            (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
            $eshk_credit,
            cptr.ldI64o(
                (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
                $eshk_credit
            ) - tmp
        );
        tmp = 0n;
    } else {
        (yield* pline_The(__s_price_is_partially_covered_by_your));
        cptr.stI64o(
            (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
            $eshk_credit,
            0n
        );
        tmp -= credit;
    }
    return tmp;
}

/** C ref: shk.c:1297 — @param {CLongLong} tmp @param {CPtr<struct monst>} shkp */
function* pay(tmp, shkp) {
    let robbed = cptr.ldI64o(
        (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
        $eshk_robbed
    );
    let balance = ((tmp <= 0n) ? tmp : (yield* check_credit(tmp, shkp)));

    if (balance > 0n)
        (yield* money2mon(shkp, balance));
    else if (balance < 0n)
        (yield* money2u(shkp, -balance));
    cptr.st1(disp, 1);
    if (robbed) {
        robbed -= tmp;
        if (robbed < 0n)
            robbed = 0n;
        cptr.stI64o(
            (cptr.ldPtro(cptr.ldPtro((shkp), $monst_mextra), $mextra_eshk)),
            $eshk_robbed,
            robbed
        );
    }
}

