    for (i = 1; i < ibillct; ++i)
        if (cptr.ldI64o2(ibill, i, $sizeof_Bill, $sortbill_item_cost) < gmin)
            gmin = cptr.ldI64o2(ibill, i, $sizeof_Bill, $sortbill_item_cost);
