                    __s_give_s_the_ld_gold_piece_s_s_asked_for,
                    (yield* shkname(shkp)),
                    ltmp,
                    (((ltmp) == 1n) ? __s_empty : __s_s),
                    (cptr.ldPtro2(genders, pronoun_gender(shkp, 3), $sizeof_Gender, $Gender_he))
