        let loan = cptr.ldI64o(eshkp, $eshk_loan);
        let sbuf = new Uint8Array(256);

        umoney = money_cnt(cptr.ldPtro(gi, $instance_globals_i_invent));
        void cptr.sprintf(
            cptr.decay(sbuf),
            __s_you_owe_s_ld_s,
            (yield* shkname(shkp)),
            dtmp,
            (yield* currency(dtmp))
        );
