/**
 * C ref: shk.c:5468
 * @param {CPtr<struct obj>} itm
 * @param {CLongLong} cost
 * @returns {CPtr<char>}
 */
function shk_embellish(itm, cost) {
    if (!rn2(3)) {
        let o;
        let choice = rn2(5);

        if (choice == 0)
            choice = (cost < 100n ? 1 : (cost < 500n ? 2 : 3));
        switch (choice) {
            case 4:
            if (cost < 10n)
                break;
            else
                o = cptr.ld1so(itm, $obj_oclass);
            if (o == NHC.FOOD_CLASS)
                return __s_gourmets_delight;
            if ((cptr.ldI32o2(
                objects,
                cptr.ldI16o(itm, $obj_otyp),
                $sizeof_objclass,
                $objclass_oc_name_known
            ) & 1) | 0
                    ? (cptr.ldI32o2(
                        objects,
                        cptr.ldI16o(itm, $obj_otyp),
                        $sizeof_objclass,
                        $objclass_oc_magic
                    ) & 1) | 0
                    : (o == NHC.AMULET_CLASS ||
                        o == NHC.RING_CLASS ||
                        o == NHC.WAND_CLASS ||
                        o == NHC.POTION_CLASS ||
                        o == NHC.SCROLL_CLASS ||
                        o == NHC.SPBOOK_CLASS
                        ? 1
                        : 0))
                return __s_painstakingly_developed;
            return __s_superb_craftsmanship;
            case 3:
            return __s_finest_quality;
            case 2:
            return __s_an_excellent_choice;
            case 1:
            return __s_a_real_bargain;
            default:
            break;
        }
    } else if (cptr.ld1so(itm, $obj_oartifact)) {
        return __s_one_of_a_kind;
    }
    return __s_dot;
}

