                    __s_donated_s_spays_off_your_debt,
                    (yield* obj_typename(cptr.ldI16o(obj_absorbed, $obj_otyp))),
                    cptr.ldI64o(eshkp, $eshk_debit) ? __s_partially : __s_empty
